internal static void testHash(ж<testing.T> Ꮡt, @string name, @string @in, @string outHex, slice<byte> oneShotResult, hash.Hash digestFunc) {
    {
        @string calculated = hex.EncodeToString(oneShotResult); if (calculated != outHex) {
            Ꮡt.Errorf("one-shot result for %s(%q) = %q, but expected %q"u8, name, @in, calculated, outHex);
            return;
        }
    }
    for (nint pass = 0; pass < 3; pass++) {
        if (pass < 2){
            io.WriteString(new sha512_internal_test_package.hash_HashᴠWriter(digestFunc), @in);
        } else {
            io.WriteString(new sha512_internal_test_package.hash_HashᴠWriter(digestFunc), @in.slice(0, len(@in) / 2));
            digestFunc.Sum(default!);
            io.WriteString(new sha512_internal_test_package.hash_HashᴠWriter(digestFunc), @in.slice(len(@in) / 2));
        }
        {
            @string calculated = hex.EncodeToString(digestFunc.Sum(default!)); if (calculated != outHex) {
                Ꮡt.Errorf("%s(%q) = %q (in pass #%d), but expected %q"u8, name, @in, calculated, pass, outHex);
            }
        }
        digestFunc.Reset();
    }
}

// Hoisted @string literals (single allocation; Go keeps these in RODATA)
internal static readonly @string sha512ˢ = "sha512"u8;

public static void TestGolden(ж<testing.T> Ꮡt) {
    cryptotest.TestAllImplementations(Ꮡt, sha512ˢ, (ж<testing.T> tΔ1) => {
        testGolden(tΔ1);
    });
}

internal partial struct testGolden_tests /*dyn*/ {
    internal @string name;
    internal Func<slice<byte>, slice<byte>> oneShotHash;
    internal hash.Hash digest;
    internal slice<sha512Test> golden;
}

internal static void testGolden(ж<testing.T> Ꮡt) {
    var tests = new testGolden_tests[]{
        new(
            "SHA512/224"u8,
            (slice<byte> @in) => {
                var a = Sum512_224(@in);
                return a[..];
            },
            New512_224(),
            golden224
        ),
        new(
            "SHA512/256"u8,
            (slice<byte> @in) => {
                var a = Sum512_256(@in);
                return a[..];
            },
            New512_256(),
            golden256
        ),
        new(
            "SHA384"u8,
            (slice<byte> @in) => {
                var a = Sum384(@in);
                return a[..];
            },
            New384(),
            golden384
        ),
        new(
            "SHA512"u8,
            (slice<byte> @in) => {
                var a = Sum512(@in);
                return a[..];
            },
            New(),
            golden512
        )
    }.slice();
    foreach (var (_, tt) in tests) {
        foreach (var (_, test) in tt.golden) {
            var @in = slice<byte>(test.@in);
            testHash(Ꮡt, tt.name, test.@in, test.@out, tt.oneShotHash(@in), tt.digest);
        }
    }
}

public static void TestGoldenMarshal(ж<testing.T> Ꮡt) {
    cryptotest.TestAllImplementations(Ꮡt, sha512ˢ, (ж<testing.T> tΔ1) => {
        testGoldenMarshal(tΔ1);
    });
}

internal partial struct testGoldenMarshal_tests /*dyn*/ {
    internal @string name;
    internal Func<hash.Hash> newHash;
    internal slice<sha512Test> golden;
}

internal static void testGoldenMarshal(ж<testing.T> Ꮡt) {
    var tests = new testGoldenMarshal_tests[]{
        new("512/224"u8, New512_224, golden224),
        new("512/256"u8, New512_256, golden256),
        new("384"u8, New384, golden384),
        new("512"u8, New, golden512)
    }.slice();
    foreach (var (_, vᴛ1) in tests) {
        ref var tt = ref heap(new testGoldenMarshal_tests(), out var Ꮡtt);
        tt = vᴛ1;

        var ttʗ1 = tt;
        Ꮡt.Run(tt.name, (ж<testing.T> tΔ1) => {
            foreach (var (_, test) in ttʗ1.golden) {
                var h = ttʗ1.newHash();
                var h2 = ttʗ1.newHash();
                io.WriteString(h, test.@in.slice(0, len(test.@in) / 2));
                var (state, err) = h._<encoding.BinaryMarshaler>().MarshalBinary();
                if (err != default!) {
                    tΔ1.Errorf("could not marshal: %v"u8, err);
                    return;
                }
                (var stateAppend, err) = h._<encoding.BinaryAppender>().AppendBinary(new slice<byte>(4, 32));
                if (err != default!) {
                    tΔ1.Errorf("could not marshal: %v"u8, err);
                    return;
                }
                stateAppend = stateAppend[4..];
                if (((sstring)state) != test.halfState) {
                    tΔ1.Errorf("New%s(%q) state = %q, want %q"u8, ttʗ1.name, test.@in, state, test.halfState);
                    continue;
                }
                if (((sstring)stateAppend) != test.halfState) {
                    tΔ1.Errorf("New%s(%q) stateAppend = %q, want %q"u8, ttʗ1.name, test.@in, stateAppend, test.halfState);
                    continue;
                }
                {
                    var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state); if (errΔ1 != default!) {
                        tΔ1.Errorf("could not unmarshal: %v"u8, errΔ1);
                        return;
                    }
                }
                io.WriteString(h, test.@in.slice(len(test.@in) / 2));
                io.WriteString(h2, test.@in.slice(len(test.@in) / 2));
                {
                    var (actual, actual2) = (h.Sum(default!), h2.Sum(default!)); if (!bytes.Equal(actual, actual2)) {
                        tΔ1.Errorf("New%s(%q) = 0x%x != marshaled 0x%x"u8, ttʗ1.name, test.@in, actual, actual2);
                    }
                }
            }
        });
    }
}

public static void TestMarshalMismatch(ж<testing.T> Ꮡt) {
    var h = new Func<hash.Hash>[]{
        New,
        New384,
        New512_224,
        New512_256
    }.slice();
    foreach (var (i, fn1) in h) {
        foreach (var (j, fn2) in h) {
            if (i == j) {
                continue;
            }
            var h1 = fn1();
            var h2 = fn2();
            var (state, err) = h1._<encoding.BinaryMarshaler>().MarshalBinary();
            if (err != default!) {
                Ꮡt.Errorf("i=%d: could not marshal: %v"u8, i, err);
                continue;
            }
            {
                var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state); if (errΔ1 == default!) {
                    Ꮡt.Errorf("i=%d, j=%d: got no error, expected one: %v"u8, i, j, errΔ1);
                }
            }
        }
    }
}

