        var h = New();
        {
            var errΔ1 = h._<encoding.BinaryUnmarshaler>().UnmarshalBinary(slice<byte>(test.state)); if (errΔ1 != default!) {
                Ꮡt.Errorf("test %d could not unmarshal: %v"u8, i, errΔ1);
                continue;
            }
        }
        var (sum, err) = safeSum(h);
        if (err != default!) {
            Ꮡt.Errorf("test %d could not sum: %v"u8, i, err);
            continue;
        }
        if (fmt.Sprintf("%x"u8, sum) != test.sum) {
